variables-radii-shadows.code:
/*
 * Corner radii (ARMS-prefixed so they don't collide with Tailwind's
 * --radius-* theme names): xs for tiny marks, sm for chips and small
 * controls, md for buttons and inputs, lg for cards and panels.
 */
--arms-radius-xs: 0.25rem;
--arms-radius-sm: 0.375rem;
--arms-radius-md: 0.5rem;
--arms-radius-lg: 0.75rem;
--arms-radius-full: 9999px;

/* Elevation: sm for resting cards, md for hover/raised, lg for overlays. */
--arms-shadow-sm: 0 2px 8px rgb(0 0 0 / 0.05);
--arms-shadow-md: 0 4px 10px rgb(0 0 0 / 0.12);
--arms-shadow-lg: 0 8px 24px rgb(0 0 0 / 0.16);

